(function(root){
const defaults={client:'Aarav Sharma',goal:'Child’s education',amount:100000,target:130000,years:3,loss:10,liquidity:'no',product:'protected',rate:6.5,cap:15,participation:80,floor:100,fee:0,term:3,up:30,flat:0,down:-30,start:2020};
const returns={2000:-13.4,2001:-15,2002:5.3,2003:76.6,2004:13,2005:38.6,2006:41.9,2007:56.8,2008:-51.3,2009:77.6,2010:19.2,2011:-23.8,2012:29.4,2013:8.1,2014:32.9,2015:-3,2016:4.4,2017:30.3,2018:4.6,2019:13.5,2020:16.1,2021:25.6,2022:5.7};
function payoff(s,r,p=s.product){let gross=p==='deposit'?s.amount*Math.pow(1+s.rate/100,s.term):p==='equity'?s.amount*Math.max(0,1+r/100):s.amount*(1+Math.max(s.floor/100-1,Math.min(s.cap/100,r/100*s.participation/100)));return Math.max(0,gross-s.amount*s.fee/100)}
function checks(s,p=s.product){let max=p==='deposit'?payoff(s,0,p):p==='protected'?payoff(s,100000,p):Infinity;let worst=payoff(s,-100,p);return [{name:'Time horizon',ok:s.term<=s.years,detail:s.term<=s.years?'Matures within the goal horizon.':'Product matures after the money is needed.'},{name:'Loss capacity',ok:worst>=s.amount*(1-s.loss/100)-.01,detail:`Modelled maximum loss: ${Math.max(0,(1-worst/s.amount)*100).toFixed(1)}% (excluding issuer default).`},{name:'Access to money',ok:s.liquidity==='no'||p==='equity',detail:s.liquidity==='no'?'No early access required.':p==='equity'?'Redeemable, but its value may fall.':'Model assumes no early withdrawal.'},{name:'Target feasibility',ok:max>=s.target,detail:Number.isFinite(max)?`Maximum maturity amount: ₹${Math.round(max).toLocaleString('en-IN')}.`:'No contractual cap; reaching the target is uncertain.'}]}
function replay(s){let points=[{year:s.start-1,index:0,value:s.amount}],growth=1;for(let i=0;i<s.term;i++){let year=s.start+i;if(returns[year]===undefined)return null;growth*=1+returns[year]/100;points.push({year,index:(growth-1)*100,value:i===s.term-1?payoff(s,(growth-1)*100):null})}return points}
const api={defaults,returns,payoff,checks,replay};root.Engine=api;if(typeof module!=='undefined')module.exports=api;
})(globalThis);
